probes="import Foundation\n\nfinal class SelectionGate: @unchecked Sendable {\n    private struct State {\n        var entered = false\n        var released = false\n        var waiters: [CheckedContinuation<Void, Never>] = []\n    }\n    private let state = AtomicStorage(State())\n    var hasEntered: Bool { state.value.entered }\n    func pause() async {\n        await withCheckedContinuation { continuation in\n            let resume = state.access { value -> Bool in\n                value.entered = true\n                if value.released { return true }\n                value.waiters.append(continuation)\n                return false\n            }\n            if resume { continuation.resume() }\n        }\n    }\n    func release() {\n        let values = state.access { value -> [CheckedContinuation<Void, Never>] in\n            value.released = true\n            let result = value.waiters\n            value.waiters.removeAll()\n            return result\n        }\n        for value in values { value.resume() }\n    }\n}\n\nfinal class SelectionNativePause: @unchecked Sendable {\n    private let state = AtomicStorage((entered: false, released: false))\n    private let semaphore = DispatchSemaphore(value: 0)\n    var hasEntered: Bool { state.value.entered }\n    func block() throws {\n        let released = state.access { value -> Bool in\n            value.entered = true\n            return value.released\n        }\n        if released { return }\n        guard semaphore.wait(timeout: .now() + 30) == .success else {\n            throw SelectionProbeError.nativePauseTimedOut\n        }\n    }\n    func release() {\n        let shouldSignal = state.access { value -> Bool in\n            guard !value.released else { return false }\n            value.released = true\n            return true\n        }\n        if shouldSignal { semaphore.signal() }\n    }\n}\n\nenum SelectionProbeError: Error, Sendable, Equatable {\n    case missingDependency, missingBinding, missingPlan, plannedNativeFailure\n    case nativePauseTimedOut, conditionTimedOut, missingManager\n}\n\nenum Anytype_Model_Account {\n    struct Info: Sendable {\n        var homeObjectID = \"\"\n        var archiveObjectID = \"\"\n        var profileObjectID = \"\"\n        var gatewayURL = \"\"\n        var accountSpaceID = \"\"\n        var spaceViewID = \"\"\n        var widgetsID = \"\"\n        var analyticsID = \"\"\n        var deviceID = \"\"\n        var networkID = \"\"\n        var techSpaceID = \"\"\n        var ethereumAddress = \"\"\n        var spaceChatID = \"\"\n        var metaDataKey = \"\"\n    }\n}\n\nstruct SelectionWorkspaceRequest: Sendable, Equatable {\n    var spaceID = \"\"\n    var withChat = false\n    static func with(_ body: (inout Self) -> Void) -> Self {\n        var value = Self()\n        body(&value)\n        return value\n    }\n}\n\nstruct SelectionWorkspaceResponse: Sendable {\n    let info: Anytype_Model_Account.Info\n}\n\nfinal class SelectionRPCPlan: Sendable {\n    let info: Anytype_Model_Account.Info\n    let fail: Bool\n    let beforeAdmission: SelectionGate?\n    let duringBody: SelectionNativePause?\n    let afterResponse: SelectionNativePause?\n    init(\n        info: Anytype_Model_Account.Info, fail: Bool = false,\n        beforeAdmission: SelectionGate? = nil,\n        duringBody: SelectionNativePause? = nil,\n        afterResponse: SelectionNativePause? = nil\n    ) {\n        self.info = info\n        self.fail = fail\n        self.beforeAdmission = beforeAdmission\n        self.duringBody = duringBody\n        self.afterResponse = afterResponse\n    }\n    func release() {\n        beforeAdmission?.release()\n        duringBody?.release()\n        afterResponse?.release()\n    }\n}\n\nfinal class SelectionRPCProbe: @unchecked Sendable {\n    struct State {\n        var plans: [SelectionRPCPlan] = []\n        var used: [SelectionRPCPlan] = []\n        var requests: [SelectionWorkspaceRequest] = []\n        var prepared = 0\n        var admitted = 0\n        var effects = 0\n        var finished = 0\n        var qos: [DispatchQoS.QoSClass] = []\n    }\n    let state = AtomicStorage(State())\n    func enqueue(_ plan: SelectionRPCPlan) { state.access { $0.plans.append(plan) } }\n    func take(_ request: SelectionWorkspaceRequest, qos: DispatchQoS.QoSClass) throws -> SelectionRPCPlan {\n        let plan = state.access { value -> SelectionRPCPlan? in\n            guard !value.plans.isEmpty else { return nil }\n            let plan = value.plans.removeFirst()\n            value.used.append(plan)\n            value.requests.append(request)\n            value.qos.append(qos)\n            return plan\n        }\n        guard let plan else { throw SelectionProbeError.missingPlan }\n        return plan\n    }\n    func releaseAll() {\n        for plan in state.value.plans + state.value.used { plan.release() }\n    }\n}\n\nstruct SelectionWorkspaceInvocation: Sendable {\n    let request: SelectionWorkspaceRequest\n    let probe: SelectionRPCProbe\n    func invoke(qos: DispatchQoS.QoSClass) async throws -> SelectionWorkspaceResponse {\n        guard let binding = InvocationDispatchContext.binding else {\n            throw SelectionProbeError.missingBinding\n        }\n        let plan = try probe.take(request, qos: qos)\n        try Task.checkCancellation()\n        let permit = try await binding.prepare(messageName: \"WorkspaceOpen\")\n        probe.state.access { $0.prepared += 1 }\n        await plan.beforeAdmission?.pause()\n        let response = try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<SelectionWorkspaceResponse, Error>) in\n            DispatchQueue.global(qos: qos).async {\n                do {\n                    let completion = try permit.begin()\n                    probe.state.access { $0.admitted += 1 }\n                    var succeeded = false\n                    defer {\n                        if !succeeded { completion.markFailed() }\n                        completion.finish()\n                        probe.state.access { $0.finished += 1 }\n                    }\n                    try plan.duringBody?.block()\n                    if plan.fail { throw SelectionProbeError.plannedNativeFailure }\n                    probe.state.access { $0.effects += 1 }\n                    succeeded = true\n                    continuation.resume(returning: SelectionWorkspaceResponse(info: plan.info))\n                    if let pause = plan.afterResponse {\n                        do { try pause.block() } catch {\n                            ProbeRegistry.assertions.access { $0.append(\"Selection completion hold timed out\") }\n                        }\n                    }\n                } catch {\n                    continuation.resume(throwing: error)\n                }\n            }\n        }\n        try Task.checkCancellation()\n        return response\n    }\n}\n\nenum ClientCommands {\n    static func workspaceOpen(_ request: SelectionWorkspaceRequest) -> SelectionWorkspaceInvocation {\n        .init(request: request, probe: SelectionRegistry.current().rpc)\n    }\n}\n\nprotocol ObjectTypeProviderProtocol: AnyObject, Sendable {\n    func prepareData(spaceId: String) async\n    func startSubscription(spaceId: String) async\n    func stopSubscription() async\n}\nprotocol PropertyDetailsStorageProtocol: AnyObject, Sendable {\n    func prepareData(spaceId: String) async\n    func startSubscription(spaceId: String) async\n    func stopSubscription() async\n}\nprotocol WidgetsObjectsStorageProtocol: AnyObject, Sendable {\n    func prepare(info: AccountInfo) async\n    func clear() async\n}\nprotocol SpaceRecencyStorageProtocol: AnyObject, Sendable {\n    func markInteraction(spaceId: String)\n}\n\nfinal class SelectionHelperProbe: ObjectTypeProviderProtocol, PropertyDetailsStorageProtocol,\n                                  WidgetsObjectsStorageProtocol, SpaceRecencyStorageProtocol, Sendable {\n    private struct State {\n        var calls: [String] = []\n        var holds: [String: [SelectionGate]] = [:]\n        var allHolds: [SelectionGate] = []\n    }\n    private let state = AtomicStorage(State())\n    var calls: [String] { state.value.calls }\n    func hold(_ key: String, at gate: SelectionGate) {\n        state.access { value in\n            value.holds[key, default: []].append(gate)\n            value.allHolds.append(gate)\n        }\n    }\n    private func perform(_ key: String) async {\n        let hold = state.access { value -> SelectionGate? in\n            value.calls.append(key)\n            guard var gates = value.holds[key], !gates.isEmpty else { return nil }\n            let first = gates.removeFirst()\n            value.holds[key] = gates\n            return first\n        }\n        await hold?.pause()\n    }\n    func prepareData(spaceId: String) async { await perform(\"prepareData:\" + spaceId) }\n    func startSubscription(spaceId: String) async { await perform(\"start:\" + spaceId) }\n    func stopSubscription() async { await perform(\"stop\") }\n    func prepare(info: AccountInfo) async { await perform(\"widgets:\" + info.accountSpaceId) }\n    func clear() async { await perform(\"clear\") }\n    func markInteraction(spaceId: String) { state.access { $0.calls.append(\"recency:\" + spaceId) } }\n    func releaseAll() { for value in state.value.allHolds { value.release() } }\n}\n\nstruct SelectionDependencies: Sendable {\n    let spaces: SpaceViewsStorage\n    let service: any WorkspaceServiceProtocol\n    let rpc: SelectionRPCProbe\n    let types: SelectionHelperProbe\n    let properties: SelectionHelperProbe\n    let widgets: SelectionHelperProbe\n    let recency: SelectionHelperProbe\n}\nenum SelectionRegistry {\n    static let dependencies = AtomicStorage<SelectionDependencies?>(nil)\n    static let bootstrap = AtomicStorage<[String]>([])\n    static let analytics = AtomicStorage(0)\n    static func current() -> SelectionDependencies {\n        guard let value = dependencies.value else { preconditionFailure(\"Selection fixture dependencies missing\") }\n        return value\n    }\n}\nextension ProbeDependencies {\n    var spaceViewsStorage: any SpaceViewsStorageProtocol { SelectionRegistry.current().spaces }\n    var workspaceService: any WorkspaceServiceProtocol { SelectionRegistry.current().service }\n    var objectTypeProvider: any ObjectTypeProviderProtocol { SelectionRegistry.current().types }\n    var propertyDetailsStorage: any PropertyDetailsStorageProtocol { SelectionRegistry.current().properties }\n    var widgetsObjectsStorage: any WidgetsObjectsStorageProtocol { SelectionRegistry.current().widgets }\n    var spaceRecencyStorage: any SpaceRecencyStorageProtocol { SelectionRegistry.current().recency }\n}\nenum PinkhaBootstrapHook {\n    static func handleSpaceActivated(spaceId: String) { SelectionRegistry.bootstrap.access { $0.append(spaceId) } }\n}\nfinal class AnytypeAnalytics: Sendable {\n    private static let singleton = AnytypeAnalytics()\n    static func instance() -> AnytypeAnalytics { singleton }\n    func logSwitchSpace() { SelectionRegistry.analytics.access { $0 += 1 } }\n}\nextension Optional {\n    var isNotNil: Bool { self != nil }\n}\n\nfinal class ReplacementWorkspaceService: WorkspaceServiceProtocol, Sendable {\n    let calls = AtomicStorage(0)\n    let shadowCalls = AtomicStorage(0)\n    let info: AccountInfo\n    init(info: AccountInfo) { self.info = info }\n    func workspaceOpen(spaceId: String, withChat: Bool) async throws -> AccountInfo {\n        calls.access { $0 += 1 }\n        return info\n    }\n    func workspaceOpenForOriginalSelection(spaceId: String) async throws -> AccountInfo {\n        shadowCalls.access { $0 += 1 }\n        return info\n    }\n}\n\nfunc selectionInfo(_ space: String = \"space-A\", view: String = \"native-view-A\",\n                   tech: String = \"actual-technical-space\") -> Anytype_Model_Account.Info {\n    var value = Anytype_Model_Account.Info()\n    value.homeObjectID = \"native-home\"\n    value.archiveObjectID = \"native-archive\"\n    value.profileObjectID = \"native-profile\"\n    value.gatewayURL = \"native-gateway\"\n    value.accountSpaceID = space\n    value.spaceViewID = view\n    value.widgetsID = \"native-widgets\"\n    value.analyticsID = \"native-analytics\"\n    value.deviceID = \"native-device\"\n    value.networkID = \"native-network\"\n    value.techSpaceID = tech\n    value.ethereumAddress = \"native-address\"\n    value.spaceChatID = \"native-chat\"\n    value.metaDataKey = \"native-metadata\"\n    return value\n}\n\n@MainActor\nfinal class SelectionFixture {\n    let account: AccountManager\n    let spaces: SpaceViewsStorage\n    let transport: SpaceSubscriptionProbe\n    let rpc: SelectionRPCProbe\n    let types = SelectionHelperProbe()\n    let properties = SelectionHelperProbe()\n    let widgets = SelectionHelperProbe()\n    let recency = SelectionHelperProbe()\n    var manager: ActiveSpaceManager?\n    private let dependencies: ProbeDependencies\n\n    init(views: [SpaceView] = [SpaceView(), SpaceView(id: \"native-view-B\", targetSpaceId: \"space-B\")],\n         service: (any WorkspaceServiceProtocol)? = nil) {\n        let account = AccountManager()\n        account.account = AccountData(id: \"actual-account\", info: selectionInfo().asModel)\n        let transport = SpaceSubscriptionProbe(views)\n        let dependencies = ProbeDependencies(\n            subscriptionStorageProvider: ProbeProvider(participant: ParticipantSubscriptionProbe([]), space: transport),\n            accountManager: account,\n            spaceViewsSubscriptionBuilder: ProbeSpaceBuilder(),\n            serverConfigurationStorage: ProbeServerConfigurationStorage()\n        )\n        ProbeRegistry.dependencies.value = dependencies\n        self.dependencies = dependencies\n        self.account = account\n        self.transport = transport\n        spaces = SpaceViewsStorage()\n        rpc = SelectionRPCProbe()\n        SelectionRegistry.dependencies.value = SelectionDependencies(\n            spaces: spaces, service: service ?? WorkspaceService(), rpc: rpc,\n            types: types, properties: properties, widgets: widgets, recency: recency\n        )\n        SelectionRegistry.bootstrap.value = []\n        SelectionRegistry.analytics.value = 0\n        ProbeRegistry.assertions.value = []\n        manager = ActiveSpaceManager()\n    }\n    func start() async { await spaces.startSubscription() }\n    func ownedManager() throws -> ActiveSpaceManager {\n        guard let manager else { throw SelectionProbeError.missingManager }\n        return manager\n    }\n    func enqueue(_ info: Anytype_Model_Account.Info = selectionInfo(),\n                 fail: Bool = false, before: SelectionGate? = nil,\n                 body: SelectionNativePause? = nil, after: SelectionNativePause? = nil) {\n        rpc.enqueue(.init(info: info, fail: fail, beforeAdmission: before,\n                          duringBody: body, afterResponse: after))\n    }\n    func releaseAll() {\n        rpc.releaseAll()\n        types.releaseAll()\n        properties.releaseAll()\n        widgets.releaseAll()\n        recency.releaseAll()\n    }\n    func stop() async {\n        releaseAll()\n        await manager?.stopSubscription()\n        await spaces.stopSubscription()\n    }\n}\n"
controls="import Foundation\nimport Testing\n\n@MainActor\nprivate func selectionWait(_ predicate: @MainActor () async -> Bool) async throws {\n    let deadline = ContinuousClock.now.advanced(by: .seconds(20))\n    while ContinuousClock.now < deadline {\n        if await predicate() { return }\n        await Task.yield()\n    }\n    throw SelectionProbeError.conditionTimedOut\n}\n\nprivate func selectionError(_ body: () throws -> Void) -> (any Error)? {\n    do { try body(); return nil } catch { return error }\n}\n\n@MainActor\nprivate func selectionAsyncError(_ body: () async throws -> Void) async -> (any Error)? {\n    do { try await body(); return nil } catch { return error }\n}\n\nprivate func errorOf<Value>(_ result: Result<Value, any Error>) -> (any Error)? {\n    if case .failure(let error) = result { return error }\n    return nil\n}\n\n@MainActor\nprivate func selectAndSubscribe(_ fixture: SelectionFixture) async throws -> OriginalActiveSpaceSelection {\n    let manager = try fixture.ownedManager()\n    _ = try await manager.setActiveSpace(spaceId: \"space-A\")\n    await manager.startSubscription()\n    return try manager.currentOriginalActiveSpaceSelection()\n}\n\n@Suite(.serialized, .timeLimit(.minutes(2)))\nstruct OriginalSelectedSpaceControls {\n    @Test @MainActor\n    func exactOriginalServiceResponseAndFrozenIdentityRejectSubstitution() async throws {\n        let fixture = SelectionFixture()\n        defer { fixture.releaseAll() }\n        await fixture.start()\n        let manager = try fixture.ownedManager()\n        let response = selectionInfo()\n        fixture.enqueue(response)\n        let value = try await manager.setActiveSpace(spaceId: \"space-A\")\n        #expect(value == response.asModel)\n        let selection = try manager.currentOriginalActiveSpaceSelection()\n        #expect(selection.accountID == \"actual-account\")\n        #expect(selection.accountInfo == response.asModel)\n        let lifetime = try #require(fixture.account.editorWriteLifetime)\n        let accountCapture = try EditorDocumentWriteCapture(lifetime)\n        let capture = try selection.capture(matching: accountCapture, spaceId: \"space-A\")\n        try capture.validate()\n        #expect(selectionError {\n            _ = try selection.capture(matching: accountCapture, spaceId: \"SPACE-A\")\n        } as? EditorDocumentWriteError == .rejected(.wrongContext))\n        let alien = try EditorDocumentWriteCapture(EditorDocumentWriteLifetime())\n        #expect(selectionError {\n            _ = try selection.capture(matching: alien, spaceId: \"space-A\")\n        } as? EditorDocumentWriteError == .rejected(.wrongContext))\n        #expect(fixture.rpc.state.value.requests == [.init(spaceID: \"space-A\", withChat: true)])\n        #expect(fixture.rpc.state.value.prepared == 1)\n        #expect(fixture.rpc.state.value.admitted == 1)\n        #expect(fixture.rpc.state.value.finished == 1)\n        #expect(fixture.rpc.state.value.qos == [.userInitiated])\n        await fixture.stop()\n\n        for response in [selectionInfo(\"wrong-space\"), selectionInfo(view: \"wrong-view\")] {\n            let rejected = SelectionFixture()\n            defer { rejected.releaseAll() }\n            await rejected.start()\n            rejected.enqueue(response)\n            let manager = try rejected.ownedManager()\n            let error = await selectionAsyncError { _ = try await manager.setActiveSpace(spaceId: \"space-A\") }\n            #expect(error as? EditorDocumentWriteError == .rejected(.wrongContext))\n            #expect(rejected.rpc.state.value.effects == 1)\n            #expect(manager.workspaceInfo == nil)\n            #expect(selectionError { _ = try manager.currentOriginalActiveSpaceSelection() } != nil)\n            await rejected.stop()\n        }\n\n        let replacement = ReplacementWorkspaceService(info: selectionInfo().asModel)\n        let foreign = SelectionFixture(service: replacement)\n        await foreign.start()\n        let foreignManager = try foreign.ownedManager()\n        let rejected = await selectionAsyncError { _ = try await foreignManager.setActiveSpace(spaceId: \"space-A\") }\n        #expect(rejected != nil)\n        #expect(replacement.calls.value == 0)\n        #expect(replacement.shadowCalls.value == 0)\n        #expect(foreign.rpc.state.value.requests.isEmpty)\n        #expect(selectionError { _ = try foreignManager.currentOriginalActiveSpaceSelection() } != nil)\n        await foreign.stop()\n    }\n\n    @Test @MainActor\n    func missingInitialViewAuthorityIsNeverRecapturedAfterNativeAwait() async throws {\n        let fixture = SelectionFixture(views: [])\n        defer { fixture.releaseAll() }\n        await fixture.start()\n        let manager = try fixture.ownedManager()\n        let gate = SelectionGate()\n        fixture.enqueue(before: gate)\n        let pending = Task { try await manager.setActiveSpace(spaceId: \"space-A\") }\n        try await selectionWait { gate.hasEntered }\n        await fixture.transport.emit([SpaceView()])\n        _ = try fixture.spaces.currentOriginalSpaceViewPermission(spaceId: \"space-A\")\n        gate.release()\n        let response = try await pending.value\n        #expect(response == selectionInfo().asModel)\n        #expect(manager.workspaceInfo == response)\n        #expect(selectionError { _ = try manager.currentOriginalActiveSpaceSelection() }\n                as? EditorDocumentWriteError == .rejected(.unqualifiedDispatch))\n        #expect(fixture.rpc.state.value.effects == 1)\n        await fixture.stop()\n    }\n\n    @Test @MainActor\n    func replacementRequestsRetireAThroughBAndABARoundTrip() async throws {\n        for returnToA in [false, true] {\n            let fixture = SelectionFixture()\n            defer { fixture.releaseAll() }\n            await fixture.start()\n            let manager = try fixture.ownedManager()\n            let gate = SelectionNativePause()\n            fixture.enqueue(body: gate)\n            fixture.enqueue(selectionInfo(returnToA ? \"space-A\" : \"space-B\",\n                                          view: returnToA ? \"native-view-A\" : \"native-view-B\"))\n            let first = Task { try await manager.setActiveSpace(spaceId: \"space-A\") }\n            try await selectionWait { gate.hasEntered }\n            let originalCapture = try #require(await manager.probeCurrentSelectionCapture())\n            let second = Task { try await manager.setActiveSpace(spaceId: \"space-B\") }\n            try await selectionWait { await manager.probeRequestedSpaceID() == \"space-B\" }\n            #expect(selectionError { try originalCapture.validate() } as? EditorDocumentWriteError == .rejected(.retired))\n            #expect(fixture.rpc.state.value.admitted == 1)\n            if returnToA {\n                let intermediate = try #require(await manager.probeCurrentSelectionCapture())\n                let third = Task { try await manager.setActiveSpace(spaceId: \"space-A\") }\n                try await selectionWait { await manager.probeRequestedSpaceID() == \"space-A\" }\n                #expect(selectionError { try intermediate.validate() } as? EditorDocumentWriteError == .rejected(.retired))\n                gate.release()\n                #expect(errorOf(await first.result) != nil)\n                #expect(errorOf(await second.result) != nil)\n                #expect(try await third.value?.accountSpaceId == \"space-A\")\n                #expect(fixture.rpc.state.value.requests.map(\\.spaceID) == [\"space-A\", \"space-A\"])\n            } else {\n                gate.release()\n                #expect(errorOf(await first.result) != nil)\n                #expect(try await second.value?.accountSpaceId == \"space-B\")\n                #expect(fixture.rpc.state.value.requests.map(\\.spaceID) == [\"space-A\", \"space-B\"])\n            }\n            try manager.currentOriginalActiveSpaceSelection().validate()\n            #expect(selectionError { try originalCapture.validate() } != nil)\n            await fixture.stop()\n        }\n    }\n\n    @Test @MainActor\n    func realPermitRejectsRetiredQueueAndAdmittedCompletionMustDrain() async throws {\n        do {\n            let fixture = SelectionFixture()\n            defer { fixture.releaseAll() }\n            await fixture.start()\n            let manager = try fixture.ownedManager()\n            let gate = SelectionGate()\n            fixture.enqueue(before: gate)\n            let request = Task { try await manager.setActiveSpace(spaceId: \"space-A\") }\n            try await selectionWait { gate.hasEntered }\n            fixture.account.account = AccountData(id: \"replacement-account\", info: selectionInfo().asModel)\n            gate.release()\n            let result = await request.result\n            #expect(errorOf(result) as? EditorDocumentWriteError == .rejected(.retired))\n            #expect(fixture.rpc.state.value.prepared == 1)\n            #expect(fixture.rpc.state.value.admitted == 0)\n            #expect(fixture.rpc.state.value.effects == 0)\n            await fixture.stop()\n        }\n        do {\n            let fixture = SelectionFixture()\n            defer { fixture.releaseAll() }\n            await fixture.start()\n            let manager = try fixture.ownedManager()\n            let body = SelectionNativePause()\n            let completion = SelectionNativePause()\n            fixture.enqueue(body: body, after: completion)\n            let requestReturned = AtomicStorage(false)\n            let request = Task {\n                defer { requestReturned.value = true }\n                return try await manager.setActiveSpace(spaceId: \"space-A\")\n            }\n            try await selectionWait { body.hasEntered }\n            let capture = try #require(await manager.probeCurrentSelectionCapture())\n            #expect(capture.source.probeAdmissionAndWaiterCounts.0 == 1)\n            fixture.account.account = AccountData(id: \"replacement-account\", info: selectionInfo().asModel)\n            #expect(selectionError { try capture.validate() } as? EditorDocumentWriteError == .rejected(.retired))\n            let stopped = AtomicStorage(false)\n            let stop = Task { await manager.stopSubscription(); stopped.value = true }\n            try await selectionWait { await manager.probeStopIsPending }\n            #expect(!stopped.value)\n            body.release()\n            try await selectionWait { completion.hasEntered && capture.source.probeAdmissionAndWaiterCounts.1 > 0 }\n            #expect(fixture.rpc.state.value.effects == 1)\n            #expect(fixture.rpc.state.value.finished == 0)\n            #expect(!requestReturned.value)\n            #expect(!stopped.value)\n            completion.release()\n            #expect(errorOf(await request.result) != nil)\n            await stop.value\n            #expect(stopped.value)\n            #expect(fixture.rpc.state.value.finished == 1)\n            #expect(capture.source.probeAdmissionAndWaiterCounts.0 == 0)\n            #expect(manager.workspaceInfo == nil)\n            #expect(selectionError { _ = try manager.currentOriginalActiveSpaceSelection() } != nil)\n            await fixture.stop()\n        }\n    }\n\n    @Test @MainActor\n    func staleNativeFailureAndHelperCompletionCannotClearReplacement() async throws {\n        for failNative in [true, false] {\n            let fixture = SelectionFixture()\n            defer { fixture.releaseAll() }\n            await fixture.start()\n            let manager = try fixture.ownedManager()\n            let native = SelectionNativePause()\n            let helper = SelectionGate()\n            fixture.enqueue(fail: failNative, body: failNative ? native : nil)\n            if !failNative { fixture.widgets.hold(\"widgets:space-A\", at: helper) }\n            fixture.enqueue(selectionInfo(\"space-B\", view: \"native-view-B\"))\n            let first = Task { try await manager.setActiveSpace(spaceId: \"space-A\") }\n            try await selectionWait { failNative ? native.hasEntered : helper.hasEntered }\n            let second = Task { try await manager.setActiveSpace(spaceId: \"space-B\") }\n            try await selectionWait { await manager.probeRequestedSpaceID() == \"space-B\" }\n            native.release()\n            helper.release()\n            #expect(errorOf(await first.result) != nil)\n            #expect(try await second.value?.accountSpaceId == \"space-B\")\n            #expect(try manager.currentOriginalActiveSpaceSelection().accountInfo.accountSpaceId == \"space-B\")\n            #expect(manager.workspaceInfo?.accountSpaceId == \"space-B\")\n            #expect(!fixture.widgets.calls.contains(\"clear\"))\n            #expect(!fixture.types.calls.contains(\"stop\"))\n            #expect(!fixture.properties.calls.contains(\"stop\"))\n            await fixture.stop()\n        }\n    }\n\n    @Test @MainActor\n    func duplicateStopBlocksNewRequestsAndFencesQueuedOldSubscriptionCallback() async throws {\n        let fixture = SelectionFixture()\n        defer { fixture.releaseAll() }\n        await fixture.start()\n        let manager = try fixture.ownedManager()\n        fixture.enqueue()\n        _ = try await manager.setActiveSpace(spaceId: \"space-A\")\n        await manager.startSubscription()\n        let oldCallback = try #require(await manager.probeCapturedSubscriptionCallback())\n        let clear = SelectionGate()\n        fixture.widgets.hold(\"clear\", at: clear)\n        let firstStop = Task { await manager.stopSubscription() }\n        try await selectionWait { clear.hasEntered }\n        let secondStop = Task { await manager.stopSubscription() }\n        #expect(await selectionAsyncError { _ = try await manager.setActiveSpace(spaceId: \"space-B\") }\n                as? EditorDocumentWriteError == .rejected(.unqualifiedDispatch))\n        await manager.startSubscription()\n        #expect(await manager.probeCapturedSubscriptionCallback() == nil)\n        clear.release()\n        await firstStop.value\n        await secondStop.value\n        #expect(fixture.widgets.calls.filter { $0 == \"clear\" }.count == 1)\n        #expect(fixture.types.calls.filter { $0 == \"stop\" }.count == 1)\n        #expect(fixture.properties.calls.filter { $0 == \"stop\" }.count == 1)\n        fixture.enqueue(selectionInfo(\"space-B\", view: \"native-view-B\"))\n        _ = try await manager.setActiveSpace(spaceId: \"space-B\")\n        await manager.startSubscription()\n        let currentCallback = try #require(await manager.probeCapturedSubscriptionCallback())\n        await oldCallback([])\n        #expect(manager.workspaceInfo?.accountSpaceId == \"space-B\")\n        try manager.currentOriginalActiveSpaceSelection().validate()\n        await currentCallback([])\n        #expect(manager.workspaceInfo == nil)\n        #expect(selectionError { _ = try manager.currentOriginalActiveSpaceSelection() } != nil)\n        #expect(fixture.rpc.state.value.requests.map(\\.spaceID) == [\"space-A\", \"space-B\"])\n        await fixture.stop()\n    }\n\n    @Test @MainActor\n    func accountAndOriginalViewRetirementAreSynchronousAndCannotReviveSelection() async throws {\n        for changeAccount in [true, false] {\n            let fixture = SelectionFixture()\n            defer { fixture.releaseAll() }\n            await fixture.start()\n            let manager = try fixture.ownedManager()\n            fixture.enqueue()\n            _ = try await manager.setActiveSpace(spaceId: \"space-A\")\n            let old = try manager.currentOriginalActiveSpaceSelection()\n            if changeAccount {\n                fixture.account.account = AccountData(id: \"restored-account\", info: selectionInfo().asModel)\n            } else {\n                await fixture.transport.emit([SpaceView(accountStatus: .spaceDeleted)])\n            }\n            #expect(selectionError { try old.validate() } as? EditorDocumentWriteError == .rejected(.retired))\n            #expect(selectionError { _ = try manager.currentOriginalActiveSpaceSelection() } != nil)\n            if changeAccount {\n                await fixture.spaces.stopSubscription()\n                await fixture.spaces.startSubscription()\n            } else {\n                await fixture.transport.emit([SpaceView()])\n            }\n            _ = try fixture.spaces.currentOriginalSpaceViewPermission(spaceId: \"space-A\")\n            #expect(selectionError { try old.validate() } as? EditorDocumentWriteError == .rejected(.retired))\n            fixture.enqueue()\n            _ = try await manager.setActiveSpace(spaceId: \"space-A\")\n            let renewed = try manager.currentOriginalActiveSpaceSelection()\n            try renewed.validate()\n            #expect(renewed.accountID == (changeAccount ? \"restored-account\" : \"actual-account\"))\n            #expect(selectionError { try old.validate() } != nil)\n            #expect(fixture.rpc.state.value.effects == 2)\n            await fixture.stop()\n        }\n    }\n\n    @Test @MainActor\n    func cancellationOfOneAwaiterDoesNotRetireSharedManagerSelection() async throws {\n        let fixture = SelectionFixture()\n        defer { fixture.releaseAll() }\n        await fixture.start()\n        let manager = try fixture.ownedManager()\n        let body = SelectionNativePause()\n        fixture.enqueue(body: body)\n        let first = Task { try await manager.setActiveSpace(spaceId: \"space-A\") }\n        try await selectionWait { body.hasEntered }\n        let second = Task { try await manager.setActiveSpace(spaceId: \"space-A\") }\n        first.cancel()\n        body.release()\n        #expect(errorOf(await first.result) is CancellationError)\n        #expect(try await second.value?.accountSpaceId == \"space-A\")\n        try manager.currentOriginalActiveSpaceSelection().validate()\n        #expect(fixture.rpc.state.value.requests.count == 1)\n        #expect(fixture.rpc.state.value.effects == 1)\n        await fixture.stop()\n    }\n\n    @Test @MainActor\n    func managerDeallocationRetiresRetainedSelectionAndCancelsConsumer() async throws {\n        let fixture = SelectionFixture()\n        defer { fixture.releaseAll() }\n        await fixture.start()\n        fixture.enqueue()\n        let selection = try await selectAndSubscribe(fixture)\n        try await selectionWait { fixture.spaces.allSpaceViewsPublisher.probeSubscriberCount == 1 }\n        weak var weakManager = fixture.manager\n        fixture.manager = nil\n        try await selectionWait { weakManager == nil }\n        #expect(selectionError { try selection.validate() } as? EditorDocumentWriteError == .rejected(.retired))\n        try await selectionWait { fixture.spaces.allSpaceViewsPublisher.probeSubscriberCount == 0 }\n        #expect(fixture.rpc.state.value.effects == 1)\n        await fixture.stop()\n    }\n\n    @Test @MainActor\n    func existingDocumentAndReadLineageCannotGrantGlobalWorkspaceMutation() async throws {\n        let fixture = SelectionFixture()\n        defer { fixture.releaseAll() }\n        await fixture.start()\n        let manager = try fixture.ownedManager()\n        let accountLifetime = try #require(fixture.account.editorWriteLifetime)\n        let source = try EditorDocumentWriteSourceBinding(\n            lifetime: EditorDocumentWriteLifetime(), accountLifetime: accountLifetime, isCurrent: { true }\n        )\n        let document = CompositionDocument()\n        let owner = try EditorDocumentWriteOwner(\n            data: .init(objectId: document.objectId, spaceId: document.spaceId, mode: document.mode),\n            lifetimeDocument: document, sourceBinding: source\n        )\n        let readError = await selectionAsyncError {\n            try await owner.performRead(contextId: document.objectId, rpcNames: [\"ObjectShow\"]) {\n                _ = try await manager.setActiveSpace(spaceId: \"space-A\")\n            }\n        }\n        #expect(readError as? EditorDocumentWriteError == .rejected(.unqualifiedDispatch))\n        let mutationError = await selectionAsyncError {\n            try await owner.performMutation(contextId: document.objectId) {\n                _ = try await manager.setActiveSpace(spaceId: \"space-A\")\n            }\n        }\n        #expect(mutationError as? EditorDocumentWriteError == .rejected(.unqualifiedDispatch))\n        #expect(fixture.rpc.state.value.requests.isEmpty)\n        fixture.enqueue()\n        let service: any WorkspaceServiceProtocol = WorkspaceService()\n        let namedError = await selectionAsyncError {\n            try await source.performRead(rpcNames: [\"ObjectShow\"]) {\n                _ = try await service.workspaceOpenForOriginalSelection(spaceId: \"space-A\")\n            }\n        }\n        #expect(namedError as? EditorDocumentWriteError == .rejected(.unqualifiedDispatch))\n        #expect(fixture.rpc.state.value.requests.count == 1)\n        #expect(fixture.rpc.state.value.prepared == 0)\n        #expect(fixture.rpc.state.value.admitted == 0)\n        #expect(fixture.rpc.state.value.effects == 0)\n        #expect(manager.workspaceInfo == nil)\n        owner.retire()\n        await fixture.stop()\n    }\n}\n"
write(out/(testdir+"/SelectionDependencyProbes.swift"),probes)
